// KMP failure function
function buildFail(p) {
  const fail=new Array(p.length).fill(0);
  let j=0;
  for (let i=1;i<p.length;i++) {
    while (j>0 && p[i]!==p[j]) j=fail[j-1]; // fall back on mismatch
    if (p[i]===p[j]) j++;
    fail[i]=j;
  }
  return fail;
}

// KMP search: all match start indices
function kmpSearch(text, pattern) {
  if (!pattern.length) return [];
  const fail=buildFail(pattern);
  const matches=[];
  let j=0;
  for (let i=0;i<text.length;i++) {
    while (j>0 && text[i]!==pattern[j]) j=fail[j-1];
    if (text[i]===pattern[j]) j++;
    if (j===pattern.length) {
      matches.push(i-pattern.length+1);
      j=fail[j-1]; // continue for overlapping matches
    }
  }
  return matches;
}

// Z-algorithm
function zArray(s) {
  const n=s.length, Z=new Array(n).fill(0);
  let L=0, R=0;
  for (let i=1;i<n;i++) {
    if (i<R) Z[i]=Math.min(R-i, Z[i-L]);
    while (i+Z[i]<n && s[Z[i]]===s[i+Z[i]]) Z[i]++;
    if (i+Z[i]>R) { L=i; R=i+Z[i]; }
  }
  return Z;
}

// Z-based pattern matching
function zSearch(text, pattern) {
  const s=pattern+'$'+text;
  const Z=zArray(s);
  const matches=[];
  for (let i=pattern.length+1;i<s.length;i++)
    if (Z[i]>=pattern.length) matches.push(i-pattern.length-1);
  return matches;
}
